// 감시할 저장소 세 곳을 한 항목씩 내보낸다. since = 지금 - 10분.
// 10분을 넉넉히 잡는 이유: n8n이 잠깐 멈췄다 돌아와도 놓치지 않게 하려는 것. 중복은 다음 노드가 걸러낸다.
const PROJECTS = ['demenpil-inc/mrb/core', 'demenpil-inc/mrb/analysis', 'demenpil-inc/mrb/frontend'];
const since = new Date(Date.now() - 10 * 60 * 1000).toISOString();
return PROJECTS.map((p) => ({ json: { project: p, enc: encodeURIComponent(p), since } }));

// GitLab이 돌려준 통과(success) 파이프라인 중 처음 보는 것만 남긴다.
// 본 것은 워크플로 정적 데이터(발행된 워크플로에서만 유지됨)에 6시간 보관한다.
const store = $getWorkflowStaticData('global');
store.seenPipelines = store.seenPipelines || {};
const now = Date.now();
for (const k of Object.keys(store.seenPipelines)) {
  if (now - store.seenPipelines[k] > 6 * 60 * 60 * 1000) delete store.seenPipelines[k];
}

const out = [];
for (const item of $input.all()) {
  const p = item.json || {};
  if (p.error || !p.id || !p.web_url) continue;          // 조회 실패 항목·빈 항목
  if (p.status !== 'success') continue;                   // API 필터가 있어도 한 번 더 확인
  const key = String(p.web_url);
  if (store.seenPipelines[key]) continue;                 // 이미 알린 것
  store.seenPipelines[key] = now;

  const m = /^https?:\/\/[^/]+\/(.+?)\/-\/pipelines\/(\d+)/.exec(p.web_url);
  const project = m ? m[1] : (p.project_id !== undefined ? String(p.project_id) : '');
  const mr = /^refs\/merge-requests\/(\d+)\//.exec(p.ref || '');
  out.push({ json: {
    project, enc: encodeURIComponent(project),
    pipeline_id: p.id, pipeline_iid: p.iid, ref: p.ref, sha: p.sha, source: p.source,
    web_url: p.web_url, updated_at: p.updated_at,
    is_mr: !!mr, mr_iid: mr ? Number(mr[1]) : null,
  } });
}
return out;

// MR 파이프라인의 DM 문안. 파이프라인 상세는 「자세히」 노드에서, MR 정보는 이 노드 입력($json)에서 온다.
function esc(s) { return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function dur(sec) {
  if (sec === null || sec === undefined || isNaN(Number(sec))) return '소요 시간 미상';
  const s = Math.round(Number(sec)); const m = Math.floor(s / 60); const r = s % 60;
  return m ? `${m}분 ${String(r).padStart(2, '0')}초` : `${r}초`;
}

const a = $('자세히').item.json || {};
const mr = $json || {};
const m = /^https?:\/\/[^/]+\/(.+?)\/-\/pipelines\/\d+/.exec(a.web_url || '');
const repo = m ? m[1] : '(저장소 미상)';
const who = a.user && a.user.name ? `${esc(a.user.name)}(${esc(a.user.username || '')})` : '(실행자 미상)';
const no = a.iid ?? a.id ?? '';
const pipe = a.web_url ? `<${a.web_url}|파이프라인 #${no}>` : `파이프라인 #${no}`;

const lines = [`*파이프라인 통과* — ${esc(repo)}`];
if (mr.web_url && mr.iid && !mr.error) {
  lines.push(`MR <${mr.web_url}|!${mr.iid}> ${esc(mr.title)}`);
  lines.push(`${esc(mr.source_branch)} → ${esc(mr.target_branch)} · ${who}`);
} else {
  const iid = (/^refs\/merge-requests\/(\d+)\//.exec(a.ref || '') || [])[1];
  lines.push(`MR !${iid || '?'} (MR 정보를 못 읽음) · ${who}`);
}
lines.push(`${dur(a.duration)} · ${pipe}`);

return { json: { text: lines.join('\n'), repo, pipeline_id: a.id, pipeline_url: a.web_url, mr_iid: mr.iid || null, mr_url: mr.web_url || null } };

// MR이 아닌 파이프라인(main 병합 뒤 · 태그)의 DM 문안. 입력($json)은 파이프라인 상세.
function esc(s) { return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function dur(sec) {
  if (sec === null || sec === undefined || isNaN(Number(sec))) return '소요 시간 미상';
  const s = Math.round(Number(sec)); const m = Math.floor(s / 60); const r = s % 60;
  return m ? `${m}분 ${String(r).padStart(2, '0')}초` : `${r}초`;
}

const a = $json || {};
const m = /^https?:\/\/[^/]+\/(.+?)\/-\/pipelines\/\d+/.exec(a.web_url || '');
const repo = m ? m[1] : '(저장소 미상)';
const who = a.user && a.user.name ? `${esc(a.user.name)}(${esc(a.user.username || '')})` : '(실행자 미상)';
const no = a.iid ?? a.id ?? '';
const pipe = a.web_url ? `<${a.web_url}|파이프라인 #${no}>` : `파이프라인 #${no}`;
// 세 저장소의 기본 브랜치는 전부 main(.gitlab-ci.yml 실독, 2026-09-02).
const where = a.tag
  ? `태그 \`${esc(a.ref)}\` (릴리스 파이프라인)`
  : a.ref === 'main'
    ? `기본 브랜치 \`${esc(a.ref)}\` (병합 뒤 파이프라인)`
    : `브랜치 \`${esc(a.ref)}\``;

const lines = [`*파이프라인 통과* — ${esc(repo)}`, `${where} · ${who}`, `${dur(a.duration)} · ${pipe}`];
return { json: { text: lines.join('\n'), repo, pipeline_id: a.id, pipeline_url: a.web_url, ref: a.ref } };

// 조건부 봇 승인 판정 — 객관적으로 확인 가능한 것만 본다.
// 하나라도 걸리면 자동승인하지 않고 사람에게 넘긴다.
const DEP = [
  /(^|\/)(package\.json|package-lock\.json|npm-shrinkwrap\.json|yarn\.lock|pnpm-lock\.yaml)$/i,
  /(^|\/)(pyproject\.toml|uv\.lock|poetry\.lock|Pipfile(\.lock)?|setup\.(cfg|py)|requirements[^\/]*\.txt)$/i,
  /(^|\/)(build\.gradle(\.kts)?|settings\.gradle(\.kts)?|gradle\.properties|libs\.versions\.toml|gradle-wrapper\.properties)$/i,
  /(^|\/)Dockerfile[^\/]*$/i,
  /(^|\/)docker-compose[^\/]*\.ya?ml$/i,
  /(^|\/)\.gitlab-ci\.yml$/i,
  /(^|\/)\.trivyignore$/i,
  /(^|\/)\.nvmrc$/i,
  /(^|\/)\.pre-commit-config\.ya?ml$/i,
  /(^|\/)(ci|docker|gradle)\//i
];

const src  = $('새 것 고르기').item.json || {};
const mr   = $('MR 정보').item.json || {};
const base = $('문안(MR)').item.json || {};
const changes = ($json && Array.isArray($json.changes)) ? $json.changes : [];

const paths = [];
for (const c of changes) {
  if (c.new_path) paths.push(c.new_path);
  if (c.old_path && c.old_path !== c.new_path) paths.push(c.old_path);
}
const hits = [...new Set(paths.filter(p => DEP.some(re => re.test(p))))];

const blockers = [];
if (hits.length) blockers.push('의존성·빌드·CI 파일 변경 (' + hits.join(', ') + ')');
if (mr.draft === true || /^\s*(draft|wip)\s*:/i.test(String(mr.title || ''))) blockers.push('초안(Draft) 상태');
if (mr.has_conflicts === true) blockers.push('병합 충돌 있음');
if (mr.blocking_discussions_resolved === false) blockers.push('미해결 토론 있음');
if (mr.state && mr.state !== 'opened') blockers.push('열린 MR이 아님 (' + mr.state + ')');
if (!changes.length) blockers.push('변경 파일 목록을 읽지 못함');

const auto_ok = blockers.length === 0;

const checked = [
  '파이프라인 통과',
  '의존성·빌드·CI 파일 무변경 (' + paths.length + '개 파일 확인)',
  '초안 아님',
  '병합 충돌 없음',
  '미해결 토론 없음'
];

const approve_comment =
  '[봇 자동승인 — 조건부]\n\n' +
  '이 승인은 사람의 보안 검토가 아닙니다. 아래 객관적 조건을 자동으로 확인한 결과입니다.\n' +
  checked.map(function (c) { return '· ' + c; }).join('\n') + '\n\n' +
  '의존성·빌드·CI 파일이 바뀌었거나 위 조건 중 하나라도 걸리면 자동승인하지 않고 사람에게 넘깁니다.\n' +
  '외부 라이브러리(SOUP) 취약점 판정이 필요한 변경은 이 경로로 승인되지 않습니다.';

const line = auto_ok
  ? '\n\n[조건 충족 — 봇 자동승인 대상]\n· 확인: ' + checked.join(' / ')
  : '\n\n[사람 확인 필요]\n· 걸린 것: ' + blockers.join(' / ');

return { json: Object.assign({}, base, {
  text: String(base.text || '') + line,
  auto_ok: auto_ok,
  blockers: blockers,
  checked_conditions: checked,
  approve_comment: approve_comment,
  changed_paths: paths,
  dep_hits: hits,
  enc: src.enc,
  mr_iid: src.mr_iid,
  project: src.project
}) };
